        $suggestions=(int)wp_count_posts('aisa_draft')->pending;
        $providerNames=array('openai'=>'OpenAI','gemini'=>'Gemini','nvidia'=>'NVIDIA','groq'=>'Groq','compatible'=>'Compatible API','local'=>'Local gateway');
